CREATE TABLE workflows (id BIGINT NOT NULL PRIMARY KEY,tenant_id BIGINT NOT NULL,entity_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,workflow_key VARCHAR(255) NOT NULL,revision BIGINT NOT NULL,name VARCHAR(255) NOT NULL,def_json JSON NOT NULL,created_at BIGINT NOT NULL,created_by BIGINT NOT NULL,updated_at BIGINT NOT NULL,updated_by BIGINT NOT NULL,deleted_at BIGINT NOT NULL DEFAULT 0,deleted_by BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 1,UNIQUE KEY uq_workflows_revision(tenant_id,entity_id,workflow_key,revision),KEY idx_workflows_scope(tenant_id,entity_id,deleted_at,updated_at,id),CHECK(id>0 AND tenant_id>0 AND entity_id>0 AND owner_id>0 AND revision>=1 AND created_at>0 AND created_by>0 AND updated_at>0 AND updated_by>0 AND version>=1),CHECK((deleted_at=0 AND deleted_by=0) OR (deleted_at>0 AND deleted_by>0))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE workflow_runs (id BIGINT NOT NULL PRIMARY KEY,tenant_id BIGINT NOT NULL,entity_id BIGINT NOT NULL,project_id BIGINT NOT NULL,owner_id BIGINT NOT NULL,def_json JSON NOT NULL,status VARCHAR(32) NOT NULL,context_json JSON NOT NULL,workspace TEXT NOT NULL,runner_handle VARCHAR(255) NOT NULL DEFAULT '',created_at BIGINT NOT NULL,created_by BIGINT NOT NULL,updated_at BIGINT NOT NULL,updated_by BIGINT NOT NULL,deleted_at BIGINT NOT NULL DEFAULT 0,deleted_by BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 1,KEY idx_workflow_runs_scope(tenant_id,entity_id,project_id,deleted_at,status,created_at,id),CHECK(id>0 AND tenant_id>0 AND entity_id>0 AND project_id>0 AND owner_id>0 AND status IN ('running','waiting_approval','completed','failed','paused','cancelled') AND created_at>0 AND created_by>0 AND updated_at>0 AND updated_by>0 AND version>=1),CHECK((deleted_at=0 AND deleted_by=0) OR (deleted_at>0 AND deleted_by>0))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE workflow_events (seq BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,id BIGINT NOT NULL UNIQUE,tenant_id BIGINT NOT NULL,entity_id BIGINT NOT NULL,project_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,run_id BIGINT NOT NULL,ts BIGINT NOT NULL,type VARCHAR(64) NOT NULL,idempotency_key VARCHAR(512) NOT NULL UNIQUE,schema_version BIGINT NOT NULL DEFAULT 1,payload_json JSON NOT NULL,KEY idx_workflow_events_run(tenant_id,entity_id,run_id,seq),CHECK(id>0 AND tenant_id>0 AND entity_id>0 AND project_id>0 AND actor_id>0 AND run_id>0 AND ts>0 AND schema_version>=1)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE node_executions (tenant_id BIGINT NOT NULL,entity_id BIGINT NOT NULL,run_id BIGINT NOT NULL,node_key VARCHAR(255) NOT NULL,attempt INT NOT NULL,status VARCHAR(32) NOT NULL,started_at BIGINT NOT NULL DEFAULT 0,completed_at BIGINT NOT NULL DEFAULT 0,error TEXT NOT NULL,PRIMARY KEY(tenant_id,entity_id,run_id,node_key,attempt),CONSTRAINT fk_node_run FOREIGN KEY(run_id) REFERENCES workflow_runs(id) ON DELETE CASCADE,CHECK(tenant_id>0 AND entity_id>0 AND run_id>0 AND attempt>=1 AND status IN ('pending','running','completed','failed','skipped','waiting_approval','retrying','paused_for_human') AND started_at>=0 AND completed_at>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE run_leases (tenant_id BIGINT NOT NULL,entity_id BIGINT NOT NULL,run_id BIGINT NOT NULL,holder_id BIGINT NOT NULL,fencing_token BIGINT NOT NULL,expires_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,PRIMARY KEY(tenant_id,entity_id,run_id),CONSTRAINT fk_lease_run FOREIGN KEY(run_id) REFERENCES workflow_runs(id) ON DELETE CASCADE,KEY idx_run_leases_expiry(expires_at),CHECK(tenant_id>0 AND entity_id>0 AND run_id>0 AND holder_id>0 AND fencing_token>=1 AND expires_at>0 AND updated_at>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
